// --- Unified endpoints ---

app.get('/api/unified/agents', (req, res) => {
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  const results = [];

  const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
  for (const agent of globalAgents) {
    results.push({ ...agent, scope: 'global', scopeLabel: 'Global', projectId: null, projectName: null });
  }

  for (const project of projects) {
    for (const agent of project.agents) {
      results.push({ ...agent, scope: 'project', scopeLabel: project.name, projectId: project.id, projectName: project.name });
    }
  }

  // Category filter
  const { category, tags } = req.query;
  let filtered = results;
  if (category) {
    filtered = filtered.filter(a => (a.frontmatter?.category || 'uncategorized') === category);
  }
  if (tags) {
    const tagList = tags.split(',').map(t => t.trim().toLowerCase());
    filtered = filtered.filter(a => {
      const agentTags = (a.frontmatter?.tags || '').split(',').map(t => t.trim().toLowerCase());
      return tagList.some(t => agentTags.includes(t));
    });
  }

  filtered.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
  res.json(filtered);
});

// ── Agent Categories ──────────────────────────────────────────────────────────

// Helper: get all agents across global + projects
function getAllAgentsFlat() {
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  return [
    ...listAgents(path.join(CLAUDE_DIR, 'agents')),
    ...projects.flatMap(p => p.agents || []),
  ];
}

// Helper: get custom categories from config
function getCustomCategories() {
  const config = loadConfig();
  return Array.isArray(config.customCategories) ? config.customCategories : [];
}

function saveCustomCategories(cats) {
  const config = loadConfig();
  config.customCategories = cats;
  saveConfig(config);
}

// GET /api/categories — list all (agent-derived + custom)
app.get('/api/categories', (req, res) => {
  const allAgents = getAllAgentsFlat();
  const custom = getCustomCategories();

  const counts = {};
  // Seed with custom categories (0 count)
  for (const c of custom) counts[c] = 0;
  // Count from agents
  for (const agent of allAgents) {
    const cat = agent.frontmatter?.category || 'uncategorized';
    counts[cat] = (counts[cat] || 0) + 1;
  }

  const categories = Object.entries(counts)
    .map(([name, count]) => ({ name, count }))
    .sort((a, b) => b.count - a.count);

  res.json(categories);
});

// POST /api/categories — create a new empty category
app.post('/api/categories', rateLimit('write'), (req, res) => {
  const { name } = req.body;
  if (!name || typeof name !== 'string') {
    return res.status(400).json({ error: 'name is required' });
  }
  const slug = name.trim().toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '');
  if (!slug) return res.status(400).json({ error: 'Invalid category name' });

  const custom = getCustomCategories();
  if (!custom.includes(slug)) {
    custom.push(slug);
    saveCustomCategories(custom);
  }

  res.json({ ok: true, name: slug });
});

// POST /api/categories/rename — rename across all agents + custom list
app.post('/api/categories/rename', rateLimit('write'), (req, res) => {
  const { oldName, newName } = req.body;
  if (!oldName || !newName || typeof oldName !== 'string' || typeof newName !== 'string') {
    return res.status(400).json({ error: 'oldName and newName are required strings' });
  }
  const slug = newName.trim().toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '');
  if (!slug) return res.status(400).json({ error: 'Invalid category name' });

  // Update custom categories list
  const custom = getCustomCategories();
  const idx = custom.indexOf(oldName);
  if (idx >= 0) custom[idx] = slug;
  else if (!custom.includes(slug)) custom.push(slug);
  saveCustomCategories(custom);

  // Bulk-update agents
  const allAgents = getAllAgentsFlat();
  let updated = 0;
  for (const agent of allAgents) {
    const cat = agent.frontmatter?.category || 'uncategorized';
    if (cat !== oldName) continue;
    try {
      const raw = fs.readFileSync(agent.path, 'utf-8');
      const { data, content: body } = matter(raw);
      data.category = slug;
      atomicWriteText(agent.path, matter.stringify(body, data));
      updated++;
    } catch { /* skip unreadable files */ }
  }

  res.json({ ok: true, updated, newName: slug });
});

// POST /api/categories/delete — reassign agents, remove from custom list
app.post('/api/categories/delete', rateLimit('write'), (req, res) => {
  const { category, reassignTo } = req.body;
  if (!category || typeof category !== 'string') {
    return res.status(400).json({ error: 'category is required' });
  }
  const target = (reassignTo && typeof reassignTo === 'string') ? reassignTo.trim() : 'uncategorized';

  // Remove from custom categories
  const custom = getCustomCategories();
  const filtered = custom.filter(c => c !== category);
  saveCustomCategories(filtered);

  // Bulk-update agents
  const allAgents = getAllAgentsFlat();
  let updated = 0;
  for (const agent of allAgents) {
    const cat = agent.frontmatter?.category || 'uncategorized';
    if (cat !== category) continue;
    try {
      const raw = fs.readFileSync(agent.path, 'utf-8');
      const { data, content: body } = matter(raw);
      data.category = target === 'uncategorized' ? undefined : target;
      atomicWriteText(agent.path, matter.stringify(body, data));
      updated++;
    } catch { /* skip unreadable files */ }
  }

  res.json({ ok: true, updated, reassignedTo: target });
});

