input.new_string:
const departmentGroups = new Map<string, UnifiedAgent[]>()
for (const a of filtered) {
  const dept = (a.frontmatter?.category as string | undefined) || 'uncategorized'
  if (!departmentGroups.has(dept)) departmentGroups.set(dept, [])
  departmentGroups.get(dept)!.push(a)
}

// Follow the server-provided category order (user-reorderable via drag-and-drop).
// Uncategorized always last; any agents with a category not returned by the
// API get appended alphabetically before uncategorized.
const categoryOrder = (categories || []).map((c) => c.name)
const seen = new Set<string>()
const orderedDepartments: string[] = []
for (const name of categoryOrder) {
  if (name === 'uncategorized') continue
  if (departmentGroups.has(name)) {
    orderedDepartments.push(name)
    seen.add(name)
  }
}
const extras = [...departmentGroups.keys()]
  .filter((d) => !seen.has(d) && d !== 'uncategorized')
  .sort()
orderedDepartments.push(...extras)
if (departmentGroups.has('uncategorized')) orderedDepartments.push('uncategorized')

